def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def_count = opp.count('D')
    my_def_count = my.count('D')

    last_me = my[-1]
    last_opp = opp[-1]

    if opp_def_count == 0:
        if my_def_count >= 2:
            if my[-1] == 'D' or (n >= 2 and my[-2] == 'D'):
                return 'D'
        if n > 5 and n % 3 == 0:
            return 'D'
        return 'C'

    retaliation_count = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i + 1] == 'D':
            retaliation_count += 1
    retaliation_rate = retaliation_count / max(1, my_def_count)

    if retaliation_rate < 0.2:
        k = 3
    elif retaliation_rate < 0.4:
        k = 4
    elif retaliation_rate < 0.6:
        k = 6
    else:
        k = 10

    if n >= 95:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            recent_opp_def = opp[-5:].count('D')
            if recent_opp_def <= 1:
                return 'C'
            else:
                return 'D'
        else:
            if opp_def_count / n > 0.5:
                return 'D'
            return 'C'

    if n > 5 and n % k == 0:
        last_def = -1
        for i in range(n - 1, -1, -1):
            if my[i] == 'D':
                last_def = i
                break
        if last_def == -1 or n - last_def >= k:
            return 'D'

    return 'C'
